const sinTildes =(s) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const POR_FAMILIA = [
  // Primero las piezas (más específicas), después las máquinas: así cada subcategoría tiene su dibujo.
  [/electroembrague/, Electroembrague],
  [/campana|embrague/, Embrague],
  [/bomba de aceite/, BombaAceite],
  [/sin ?fin|engranaje/, Engranaje],
  [/bombin/, Bombin],
  [/llave.*pas|pases de combustible/, LlavePaso],
  [/filtros? de combustible/, FiltroCombustible],
  [/filtros? de aceite/, FiltroAceite],
  [/filtro/, FiltroAire],
  [/manguera/, Manguera],
  [/tanque|deposito/, Tanque],
  [/bobina/, Bobina],
  [/escape/, Escape],
  [/reten|o.?ring/, Reten],
  [/tapas? de cilindro/, Culata],
  [/piston|cilindro/, Piston],
  [/\baros\b/, Aros],
  [/ciguenal/, Ciguenal],
  [/valvula/, Valvula],
  [/accesorio|herramienta/, Herramienta],
  [/cable/, Cable],
  [/cuchilla/, Cuchilla],
  [/rueda|neumatico|camara/, Rueda],
  [/polea/, Polea],
  [/torreta|carcasa|eje/, Torreta],
  [/espada/, Espada],
  [/cadena/, Cadena],
  [/correa/, Correa],
  [/cabezal|tanza/, Cabezal],
  [/arranque/, Arranque],
  [/carbur|punzuar/, CarburadorPieza],
  [/junta|diafragma/, Junta],
  [/encendido|bujia/, Bujia],
  [/arnes/, Arnes],
  [/motosierra/, Motosierra],
  [/minitractor|tractor/, Minitractor],
  [/desmalezadora|bordeadora/, Desmalezadora],
  [/cortar|cortadora|cesped/, Cortadora],
  [/sopladora/, Sopladora],
  [/hidrolavadora|motobomba/, Hidrolavadora],
  [/motores|motor 4t|motor/, Motor],
  [/generador/, Generador],
];

/** Dibujo de línea que corresponde a una familia del catálogo (por su nombre). */
export function dibujoFamilia(nombre = '') {
  const n = sinTildes(nombre);
  return (POR_FAMILIA.find(([re]) => re.test(n)) || [null, Universal])[1];
}

